\therefore \quad \begin{aligned}
\frac{1}{2} &=\frac{300}{T_{2}} \\
T_{2} &=600 \mathrm{~K} \\
T_{2} &=327^{\circ} \mathrm{C}
\end{aligned}

So, $\Delta t=327-27=300^{\circ} \mathrm{C}$

Required heat, $Q \propto r^{2}$
where $r$ is the radius.

\begin{aligned}
\therefore \quad \frac{Q_{1}}{Q_{2}} &=\frac{r_{1}^{2}}{r_{2}^{2}} \\
\frac{Q_{1}}{Q_{2}} &=\frac{(1.5)^{2}}{(1)^{2}} \\
\frac{Q_{1}}{Q_{2}} &=\frac{9}{4}
\end{aligned}
